// Package store provides PostgreSQL access: the connection pool, embedded
// schema migrations and the typed queries generated by sqlc from queries/.
package store

import (
	"context"
	"embed"
	"errors"
	"fmt"
	"io/fs"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/jackc/pgx/v5/stdlib"
	"github.com/pressly/goose/v3"
	"github.com/pressly/goose/v3/lock"
)

//go:embed migrations/*.sql
var migrations embed.FS

// Role values stored in users.role.
const (
	RoleAdmin  = "admin"
	RoleViewer = "viewer"
)

var (
	// ErrNotFound is returned when a requested row does not exist.
	ErrNotFound = errors.New("not found")
	// ErrLastAdmin is returned when a change would leave no administrator.
	ErrLastAdmin = errors.New("at least one administrator must remain")
)

// Open connects to PostgreSQL and verifies the connection.
func Open(ctx context.Context, databaseURL string) (*pgxpool.Pool, error) {
	pool, err := pgxpool.New(ctx, databaseURL)
	if err != nil {
		return nil, fmt.Errorf("parse database URL: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("connect to database: %w", err)
	}
	return pool, nil
}

// Migrate applies all pending schema migrations. Goose holds a PostgreSQL
// advisory lock while migrating, so concurrent starts cannot interleave.
func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	sub, err := fs.Sub(migrations, "migrations")
	if err != nil {
		return err
	}
	db := stdlib.OpenDBFromPool(pool)
	defer func() { _ = db.Close() }()
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return err
	}
	p, err := goose.NewProvider(goose.DialectPostgres, db, sub, goose.WithSessionLocker(locker))
	if err != nil {
		return fmt.Errorf("prepare migrations: %w", err)
	}
	if _, err := p.Up(ctx); err != nil {
		return fmt.Errorf("apply migrations: %w", err)
	}
	return nil
}

// SetUserRole changes a user's role. It refuses to demote the last
// administrator, holding row locks on all administrators so that concurrent
// demotions cannot both succeed.
func SetUserRole(ctx context.Context, pool *pgxpool.Pool, id int64, role string) (User, error) {
	var out User
	err := pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
		q := New(tx)
		admins, err := q.LockAdmins(ctx)
		if err != nil {
			return err
		}
		if role != RoleAdmin && len(admins) == 1 && admins[0] == id {
			return ErrLastAdmin
		}
		out, err = q.SetUserRole(ctx, SetUserRoleParams{ID: id, Role: role})
		if errors.Is(err, pgx.ErrNoRows) {
			return ErrNotFound
		}
		return err
	})
	return out, err
}

// ResetMFA removes a user's TOTP enrolment and recovery codes and ends all
// of the user's sessions, in one transaction. The user enrols again at the
// next sign-in. It returns ErrNotFound for an unknown user.
func ResetMFA(ctx context.Context, pool *pgxpool.Pool, userID int64) error {
	return pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
		q := New(tx)
		if _, err := q.GetUser(ctx, userID); errors.Is(err, pgx.ErrNoRows) {
			return ErrNotFound
		} else if err != nil {
			return err
		}
		if err := q.ResetTOTP(ctx, userID); err != nil {
			return err
		}
		if err := q.DeleteRecoveryCodes(ctx, userID); err != nil {
			return err
		}
		return q.DeleteUserSessions(ctx, userID)
	})
}
